    static let BYTE_SHA256: VOffset = 14
    static let BYTE_SHA512: VOffset = 16
    static let CID: VOffset = 18
    static let MULTIFORMAT_ADDRESS: VOffset = 20
    static let CUSTODY: VOffset = 22
    static let RETRIEVED_AT: VOffset = 24
  }

